local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Lua-backed Hyprland bindings are reported by hyprctl as __lua with an
-- internal numeric action id. Provide descriptions so the launcher can show
-- what each shortcut does instead of that implementation detail.
local function describedBind(key, dispatcher, description, options)
	options = options or {}
	options.description = description
	return hl.bind(key, dispatcher, options)
end

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
describedBind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal), "Open terminal")
-- SUPER + K = searchable Hyprland shortcuts and running-app switcher
describedBind(mainMod .. " + K", hl.dsp.exec_cmd("/home/maxii/.local/bin/hypr-shortcut-launcher"), "Open shortcuts and apps launcher")
-- SUPER + N = floating iced scratchpad notepad (toggle)
describedBind(mainMod .. " + N", hl.dsp.exec_cmd(HYPR_SCRATCH), "Toggle scratchpad notepad")
-- SUPER + C = force-close the focused app (SIGKILL, no "you sure?" prompt).
-- hl.dsp.window.kill() kills the process instead of sending a graceful close
-- request, so apps can't show save/close confirmations.
describedBind(mainMod .. " + C", hl.dsp.window.kill(), "Kill focused window")

-- SUPER + SHIFT + C = graceful close: ASK the focused app to shut down, so an app
-- that supports the request can prompt to save. An app that ignores it is killed
-- by the compositor regardless — silently, since this bind says nothing.
describedBind(mainMod .. " + SHIFT + C", hl.dsp.window.close(), "Close focused window")

describedBind(mainMod .. " + M", hl.dsp.exit(), "Log out or exit Hyprland")
describedBind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager), "Open file manager")
describedBind(mainMod .. " + W", hl.dsp.exec_cmd("firefox"), "Open Firefox")
-- SUPER + D = launch a second copy of the app in the focused window, on the
-- current workspace, via that window's own command line rather than its class
-- name. Steam moved to SUPER + T only because this chord was taken; whether a
-- Steam window survives the script is incidental to the guard it runs, which
-- refuses whatever the host cannot resolve and knows nothing about Steam.
describedBind(mainMod .. " + T", hl.dsp.exec_cmd("steam"), "Open Steam")
describedBind(mainMod .. " + D", hl.dsp.exec_cmd("/home/maxii/.config/hypr/scripts/duplicate-window.sh"), "Duplicate focused window")
describedBind(mainMod .. " + SHIFT + V", hl.dsp.window.float({ action = "toggle" }), "Toggle focused window floating")
-- SUPER on its own = the rofi app launcher, toggled: SUPER again closes it.
-- `menu` (above) is the toggle wrapper, not the rofi command line: the wrapper
-- owns the rofi flags, because a multi-word argument appended to a bind here
-- does not survive dispatch intact.
--
-- This is the "modkey only" bind, which is a special case: a bare `bind = SUPER,
-- ...` registers fine (hyprctl shows it, with an empty key) but never reaches
-- the dispatcher. The documented way to bind a modkey by itself is the release
-- form with the target key named explicitly -- see "Binding modkeys only" in
-- the wiki (https://wiki.hypr.land/Configuring/Binds/), whose example is
-- `bindr = SUPER ALT, Alt_L, exec, amongus`. Naming the key and adding the
-- release flag is what makes it a modkey bind rather than a chord that is
-- missing its second key.
--
-- allow_input_capture is what makes the closing half of the toggle work: rofi
-- grabs the keyboard while it is open, and a normal bind is not dispatched
-- while a client holds that grab, so SUPER again would be swallowed by rofi
-- instead of reaching this bind.
--
-- Known risk: upstream issue hyprwm/Hyprland#6946 tracks this regressing, with
-- a report of it still failing on 0.56.2 (the version this session runs). If
-- bare SUPER stays dead, put the launcher back on a chord -- SUPER + R worked.
describedBind(
	mainMod .. " + SUPER_L",
	hl.dsp.exec_cmd(menu),
	"Open application launcher",
	{ release = true, allow_input_capture = true }
)
-- Clipboard history (cliphist): SUPER + V opens history in rofi,
-- picking an entry copies it back to the clipboard (paste with Ctrl+V / SUPER+V)
describedBind(
	mainMod .. " + V",
	hl.dsp.exec_cmd("cliphist list | rofi -dmenu -i -monitor DP-1 | cliphist decode | wl-copy"),
	"Open clipboard history"
)
describedBind(mainMod .. " + P", hl.dsp.window.pseudo(), "Toggle pseudo-terminal")
describedBind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "maximized" }), "Maximize focused window") -- fills monitor, keeps gaps + borders
describedBind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen(), "Toggle fullscreen") -- fills monitor, no gaps/borders
describedBind(mainMod .. " + J", hl.dsp.layout("togglesplit"), "Toggle split layout") -- dwindle only

-- Move focus with mainMod + arrow keys
describedBind(mainMod .. " + left", hl.dsp.focus({ direction = "left" }), "Focus window left")
describedBind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }), "Focus window right")
describedBind(mainMod .. " + up", hl.dsp.focus({ direction = "up" }), "Focus window up")
describedBind(mainMod .. " + down", hl.dsp.focus({ direction = "down" }), "Focus window down")

-- Rearrange windows with the keyboard:
--   SUPER + SHIFT + arrows = move focused window in a direction
--     (works even when fullscreen: script unfullscreens, moves, refullscreens)
--   SUPER + ALT + arrows   = swap focused window with its neighbor
describedBind(mainMod .. " + SHIFT + left", hl.dsp.exec_cmd("/home/maxii/.config/hypr/scripts/move-fullscreen.sh left"), "Move focused window left")
describedBind(mainMod .. " + SHIFT + right", hl.dsp.exec_cmd("/home/maxii/.config/hypr/scripts/move-fullscreen.sh right"), "Move focused window right")
describedBind(mainMod .. " + SHIFT + up", hl.dsp.exec_cmd("/home/maxii/.config/hypr/scripts/move-fullscreen.sh up"), "Move focused window up")
describedBind(mainMod .. " + SHIFT + down", hl.dsp.exec_cmd("/home/maxii/.config/hypr/scripts/move-fullscreen.sh down"), "Move focused window down")
describedBind(mainMod .. " + ALT + left", hl.dsp.window.swap({ direction = "left" }), "Swap focused window left")
describedBind(mainMod .. " + ALT + right", hl.dsp.window.swap({ direction = "right" }), "Swap focused window right")
describedBind(mainMod .. " + ALT + up", hl.dsp.window.swap({ direction = "up" }), "Swap focused window up")
describedBind(mainMod .. " + ALT + down", hl.dsp.window.swap({ direction = "down" }), "Swap focused window down")

-- Screenshots with grim + slurp
--   Print       = current active monitor only
--   SHIFT+Print = region select, confined to the active monitor (edges act as snap boundaries)
describedBind("print", hl.dsp.exec_cmd("mkdir -p /home/maxii/Pictures/Screenshots && f=/home/maxii/Pictures/Screenshots/$(date +%F_%H-%M-%S).png && grim -o \"$(hyprctl activeworkspace -j | jq -r .monitor)\" - | tee \"$f\" | wl-copy && notify-send -a screenshot 'Screenshot saved (active monitor)' \"$(basename \"$f\")\""), "Take screenshot of active monitor")
describedBind("SHIFT + print", hl.dsp.exec_cmd("mkdir -p /home/maxii/Pictures/Screenshots && f=/home/maxii/Pictures/Screenshots/$(date +%F_%H-%M-%S).png && grim -g \"$(slurp -o \"$(hyprctl activeworkspace -j | jq -r .monitor)\")\" - | tee \"$f\" | wl-copy && notify-send -a screenshot 'Screenshot saved (region)' \"$(basename \"$f\")\""), "Take screenshot of selected region")

-- SUPER + Print = open the most recent screenshot with qView
describedBind(mainMod .. " + print", hl.dsp.exec_cmd("latest=$(ls -t /home/maxii/Pictures/Screenshots/*.png 2>/dev/null | head -1); [ -n \"$latest\" ] && flatpak run com.interversehq.qView \"$latest\" || notify-send -u critical -a screenshot 'No screenshots yet'"), "Open latest screenshot")

-- Switch workspaces with mainMod + [0-9]
-- Send active window to a workspace without following it with mainMod + SHIFT + [0-9]
-- Move active window to a workspace and follow it with mainMod + CTRL + [0-9]
for i = 1, 10 do
	local key = i % 10 -- 10 maps to key 0
	describedBind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }), "Focus workspace " .. i)
	describedBind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i, follow = false }), "Send focused window to workspace " .. i)
	describedBind(mainMod .. " + CTRL + " .. key, hl.dsp.window.move({ workspace = i }), "Move focused window to workspace " .. i .. " (follow)")
end

-- Example special workspace (scratchpad)
describedBind(mainMod .. " + S", hl.dsp.workspace.toggle_special("magic"), "Toggle magic workspace")
describedBind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }), "Move focused window to magic workspace")

-- The NZXT Lift Elite's two thumb buttons. Codes read off the raw evdev stream
-- on /dev/input/event2 rather than guessed: 276 (BTN_EXTRA) is the front button,
-- 275 (BTN_SIDE) the back one. Hyprland has no per-device binds, so these are
-- global -- but no other attached mouse emits 275/276 (the GMMK trackball module
-- declares them and never sends them).
--
-- The workspace chords reuse the dispatchers from the SUPER + [0-9] loop above:
-- SUPER = switch, SUPER + SHIFT = send the window without following. Chords and
-- bare buttons coexist; Hyprland matches binds on (modmask, key).
describedBind("CTRL + mouse:276", hl.dsp.workspace.toggle_special("magic"), "Toggle magic workspace (mouse)")
-- The "out" move has no keyboard equivalent: hl.window.move has no `previous`
-- selector, but `monitor = "current"` resolves to the focused monitor's
-- m_activeWorkspace, which stays the normal workspace sitting behind the
-- scratchpad. Moving out of a special workspace also closes it.
describedBind("CTRL + mouse:275", hl.dsp.window.move({ monitor = "current" }), "Send magic-workspace window back to the workspace behind it (mouse)")
describedBind(mainMod .. " + mouse:275", hl.dsp.focus({ workspace = 1 }), "Focus workspace 1 (mouse)")
describedBind(mainMod .. " + mouse:276", hl.dsp.focus({ workspace = 4 }), "Focus workspace 4 (mouse)")
describedBind(mainMod .. " + SHIFT + mouse:275", hl.dsp.window.move({ workspace = 1, follow = false }), "Send focused window to workspace 1 (mouse)")
describedBind(mainMod .. " + SHIFT + mouse:276", hl.dsp.window.move({ workspace = 4, follow = false }), "Send focused window to workspace 4 (mouse)")

-- Scroll through existing workspaces with mainMod + scroll
describedBind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }), "Focus next existing workspace")
describedBind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }), "Focus previous existing workspace")

-- Move/resize windows with mainMod + LMB/RMB and dragging
describedBind(mainMod .. " + mouse:272", hl.dsp.window.drag(), "Drag focused window", { mouse = true })
describedBind(mainMod .. " + mouse:273", hl.dsp.window.resize(), "Resize focused window", { mouse = true })

-- Click outside rofi to close it (rofi's own -click-to-exit is broken on Wayland:
-- rofi only creates its own layer surface, so outside clicks never reach it)
describedBind(
	"mouse:272",
	hl.dsp.exec_cmd("/home/maxii/.config/hypr/scripts/rofi-outside-click.sh"),
	"Close rofi on outside click (LMB)",
	{ non_consuming = true }
)
describedBind(
	"mouse:273",
	hl.dsp.exec_cmd("/home/maxii/.config/hypr/scripts/rofi-outside-click.sh"),
	"Close rofi on outside click (RMB)",
	{ non_consuming = true }
)

-- Click outside the scratchpad notepad to save and hide it. Same reason as the
-- rofi binds above, and for the same reason it has to be asked of the
-- compositor rather than done in the app: GTK4 removed the client-side pointer
-- grab API, so a window that is not grabbing never hears about clicks outside
-- itself, and the notepad cannot grab without losing focus-away dismissal.
--
-- Unlike the rofi script this must not kill anything -- the notepad has unsaved
-- text and is expected to still be there for the next hotkey -- so it tells the
-- running instance to save and hide, over the notepad's own socket.
-- `non_consuming` for the same reason as rofi: the click has to reach the window
-- underneath, so that focusing something else and dismissing the notepad are one
-- gesture rather than two.
--
-- `--outside-click` is a mode of the notepad's own binary rather than a script,
-- so there is nothing to keep in sync and nothing to install but the binary. It
-- does not touch the socket unless the click landed outside, and does nothing at
-- all if the notepad is not running, so it is safe to leave bound to bare clicks.
--
-- A third and fourth bind on these two buttons, which Hyprland allows; the
-- mouse:272/273 drag and resize binds above are on a modifier and do not
-- collide.
describedBind(
	"mouse:272",
	hl.dsp.exec_cmd(HYPR_SCRATCH .. " --outside-click"),
	"Dismiss scratchpad notepad on outside click (LMB)",
	{ non_consuming = true }
)
describedBind(
	"mouse:273",
	hl.dsp.exec_cmd(HYPR_SCRATCH .. " --outside-click"),
	"Dismiss scratchpad notepad on outside click (RMB)",
	{ non_consuming = true }
)

-- Laptop multimedia keys for volume and LCD brightness
describedBind(
	"XF86AudioRaiseVolume",
	hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"),
