-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

hl.window_rule({
	-- Ignore maximize requests from all apps. You'll probably like this.
	name = "suppress-maximize-events",
	match = { class = ".*" },

	suppress_event = "maximize",
})

hl.window_rule({
	-- Fix some dragging issues with XWayland
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},

	no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Iced glass and overlay behaviour for the scratchpad notepad. The panel is
-- only 0.72 opaque in GTK, so blur plus the global vibrancy setting is what
-- produces the frost. `no_blur = false` means "do blur this window"; size,
-- passes and vibrancy come from the global decoration.blur block and are
-- shared with every other window, so this rule can only ask for blur on or
-- off, not tune it.
--
-- The notepad is a normal toplevel, not a layer surface. That is deliberate: a
-- layer surface that holds the keyboard traps the session -- Hyprland will not
-- move focus off it, so clicking away does nothing and the notepad can only be
-- dismissed by its own hotkey. As a real window it gets honest focus
-- semantics, so it closes when you click away or focus something else.
--
-- That means the overlay look is the compositor's job. GTK4 removed the client
-- side window hints (keep-above, skip-taskbar, type), so without this rule the
-- notepad would open tiled and snapped into the layout. `pin` keeps it above
-- everything; `float` keeps it out of the layout; `center` puts it in the
-- middle of the monitor it opens on, which the app then corrects to the main
-- display. `no_focus` is deliberately NOT set: the notepad has to take the
-- keyboard when it opens.
--
-- The class is the GTK application ID, verbatim: GTK4 puts it on the toplevel
-- as the Wayland app id and Hyprland reports that as the class. It is not
-- `hypr-scratch` as it was when the notepad was a layer surface with an
-- explicit namespace.
--
-- The `.*` on both sides is not decoration. Hyprland matches a window rule
-- against the *whole* class rather than a substring of it, so a bare
-- "HyprScratch" matches nothing at all and the notepad quietly opens tiled and
-- unfocused.
--
-- Every key below is checked against Hyprland's own list of window-rule effect
-- keys (src/desktop/rule/windowRule/WindowRuleEffectContainer.cpp). Two keys
-- that used to be here are not on it, and both were silently doing nothing:
--
--   no_border  There is no such effect. The list has `border_size`, which is
--              the real spelling; see below.
--   suppress_event as a table  This one takes a *space-separated string*,
--              not a list. A table is the kind of thing `luac -p` happily
--              accepts and Hyprland then ignores, which is why it survived.
--
-- `rounding = 10` is `decoration.rounding` restated. The notepad's corners are
-- actually painted by the app's own CSS, not by this -- with `rounding = 0`
-- here the compositor leaves the surface square and the arc is still there --
-- but setting both to the same number means the two layers cannot disagree
-- about how round the window is, whichever one ends up painting.
hl.window_rule({
	name = "hypr-scratch-overlay",
	match = { class = ".*HyprScratch.*" },
	float = true,
	center = true,
	pin = true,
	border_size = 0,
	no_shadow = true,
	no_anim = true,
	no_blur = false,
	rounding = 10,
	suppress_event = "maximize fullscreen",
})

-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})

-- Open every new application window on the main center monitor.
hl.window_rule({
	name = "open-on-main-monitor",
	match = { class = ".*" },
	monitor = "DP-1",
})

-- Steam games are fullscreen on the main panel, workspace 10. Must come AFTER
-- the catch-all above: windowrules match top-to-bottom and the first match
-- wins, so the `class = ".*"` rule would otherwise consume these windows and
-- this one would never fire.
--
-- The monitor is keyed by NAME, not id. Monitor ids are enum-order and shift
-- across reboots (id 1 currently resolves to DP-2, a different panel), so a
-- numeric `monitor = 1` lands games on the wrong screen unpredictably.
--
-- `no_follow_mouse` opts the game out of `input.follow_mouse`. A fullscreen
-- game captures the pointer, so any mouse move Hyprland reads over the game
-- surface would hand focus away from it and the in-game cursor sticks where it
-- was captured. The opt-out only does anything while `follow_mouse` is non-zero,
-- so the two settings are coupled and must be read together.
hl.window_rule({
	name = "steam-game-fullscreen",
	match = { class = "^steam_app_\\d+$" },
	fullscreen = true,
	monitor = "DP-1",
	workspace = 10,
	no_follow_mouse = true,
})

-- Workspace 10 is the Steam-games workspace, and everything on it is
-- fullscreen, so a border and rounded corners draw over nothing but the game's
-- own pixels — visual noise, and a visible seam at the screen edges.
--
-- These keys are `no_border` / `no_rounding` on 0.56.2. `border = false` /
-- `rounding = false` is the 0.47-era spelling of the same thing and is now
-- silently dropped as an unknown field — third time this file got bitten by it
-- (window-rule `no_border`, `suppress_event` as a table, this). Neither the lua
-- binding nor the json printer complains; `configerrors` is the only report.
--
-- That spelling is workspace-rule-specific: on `hl.window_rule` `no_border` is
-- an unknown field and `border_size` is the equivalent — see the
-- `hypr-scratch-overlay` comment above.
hl.workspace_rule({
	workspace = "10",
	no_border = true,
	no_rounding = true,
})

-- Steam notification toasts (friend online, achievements) must survive a
-- fullscreen game on another workspace. Without this they silently vanish, and
-- the cause is compositor-side, not Steam: the toasts are XWayland windows of
-- class `steam` titled `notificationtoasts_<n>_desktop`, and Hyprland culls
-- every window that is not "allowed over fullscreen"
-- (Renderer.cpp, shouldRenderWindow). The policy that grants it
-- (WindowFullscreenPolicy.cpp, effectiveAllowedOverFullscreen) allows only four
-- cases: the fullscreen window itself, a *pinned* window, one explicitly
-- permitted, or one grouped with the fullscreen window. A toast is none of
-- those, so it gets dropped.
--
-- `pin` satisfies the policy in one move and also fixes the second half of the
-- bug: pinned windows render on every workspace, so a toast raised while
-- Steam itself sits on another workspace still appears over the game. That is
-- the whole reason these were invisible with the game on ws4 and Steam on 1-3.
--
-- `float` is not optional. Pinning is ignored for tiled windows, so without it
-- the pin silently does nothing.
--
-- `no_focus` because a notification must never steal focus from a running game;
-- the toast still draws and still takes clicks.
--
-- Tradeoff: a pinned window renders on every connected monitor, so the toast
-- appears in the corner of all three displays. That is the cost of not missing
-- it, and it is why this is scoped by title to the toasts alone rather than
-- pinning all of Steam.
hl.window_rule({
	name = "steam-toast-over-fullscreen",
	match = {
		class = "^steam$",
		title = "^notificationtoasts_.*_desktop$",
	},
	float = true,
	pin = true,
	no_focus = true,
})
